/*
 * This is not jQuery 2.2.4.
 *
 * JMRI no longer includes jQuery 2.2.4. Web pages written for earlier versions
 * of JMRI, and edited copies of JMRI's web files kept in a user's own web
 * folder, may still load /js/jquery-2.2.4.min.js. In its place this file loads
 * JMRI's jQuery 3.7.1 and jQuery Migrate 3.6.0, which puts back most of what
 * jQuery 3 removed, so those pages keep working.
 *
 * A page that loads this file works with this version of JMRI and with earlier
 * ones, which still have the real jQuery 2.2.4. Pages that only need to run on
 * this and later versions should load /js/jquery-3.7.1.min.js instead; see
 * "Updating Custom Pages to jQuery 3" in the web server help. This file will be
 * removed in a later version of JMRI.
 */
(function () {
    "use strict";
    var script = document.currentScript;
    var folder = (script && script.src) ? script.src.replace(/[^\/]*$/, "") : "/js/";
    if (window.console && window.console.warn) {
        window.console.warn("JMRI: this page loads jquery-2.2.4.min.js, which JMRI no longer includes;"
            + " jQuery 3.7.1 and jQuery Migrate are loaded in its place."
            + " See Updating Custom Pages to jQuery 3 in the JMRI web server help.");
    }
    // written into the page while it is being read, so both run, in order,
    // before the page's next script, as jQuery 2.2.4 itself would have
    document.write("<script src=\"" + folder + "jquery-3.7.1.min.js\"><\/script>"
        + "<script src=\"" + folder + "jquery-migrate-3.6.0.js\"><\/script>");
}());
